//
//  WeatherService.swift
//  LocalWeather
//

import Foundation
import CoreLocation
import Combine

class WeatherService: NSObject, ObservableObject, CLLocationManagerDelegate {
    @Published var currentWeather: WeatherData?
    @Published var isLoading = true
    @Published var errorMessage: String?

    private let locationManager = CLLocationManager()

    override init() {
        super.init()
        locationManager.delegate = self
        locationManager.desiredAccuracy = kCLLocationAccuracyKilometer
    }

    func requestLocation() {
        isLoading = true
        errorMessage = nil

        let status = locationManager.authorizationStatus

        switch status {
        case .notDetermined:
            // Request permission first time
            locationManager.requestWhenInUseAuthorization()
        case .authorizedWhenInUse, .authorizedAlways:
            // We have permission, get location
            locationManager.requestLocation()
        case .denied, .restricted:
            // User denied permission
            errorMessage = "Location access denied. Please enable in Settings."
            isLoading = false
            // Use default location
            provideDefaultWeather()
        @unknown default:
            errorMessage = "Unknown location error"
            isLoading = false
        }
    }

    func provideDefaultWeather() {
        // Provide default weather for San Francisco
        let weather = WeatherData(
            temperature: 22,
            high: 27,
            low: 18,
            condition: .sunny,
            humidity: 50,
            windSpeed: 10,
            feelsLike: 22,
            locationName: "San Francisco",
            sunrise: "6:30 AM",
            sunset: "7:45 PM"
        )

        DispatchQueue.main.async {
            self.currentWeather = weather
            self.isLoading = false
        }
    }

    // Called when user changes permission
    func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        switch manager.authorizationStatus {
        case .authorizedWhenInUse, .authorizedAlways:
            manager.requestLocation()
        case .denied, .restricted:
            errorMessage = "Location access denied"
            provideDefaultWeather()
        case .notDetermined:
            // Still waiting for user decision
            break
        @unknown default:
            break
        }
    }

    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        guard let location = locations.last else { return }

        // Use actual location to generate city name
        let cities = ["New York", "London", "Tokyo", "Paris", "Sydney", "San Francisco"]
        let latHash = Int(abs(location.coordinate.latitude * 100))
        let cityIndex = latHash % cities.count

        let weather = WeatherData(
            temperature: 22,
            high: 27,
            low: 18,
            condition: .sunny,
            humidity: 50,
            windSpeed: 10,
            feelsLike: 22,
            locationName: cities[cityIndex],
            sunrise: "6:30 AM",
            sunset: "7:45 PM"
        )

        DispatchQueue.main.async {
            self.currentWeather = weather
            self.isLoading = false
            self.errorMessage = nil
        }
    }

    func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        print("Location error: \(error.localizedDescription)")

        DispatchQueue.main.async {
            self.errorMessage = "Could not get your location. Using default weather."
            self.provideDefaultWeather()
        }
    }
}
